-- ================================================-- 给 wecom_test_messages 表添加 pdf_url 字段-- ================================================SET @dbname = DATABASE();SET @tablename = 'wecom_test_messages';SET @columnname = 'pdf_url';SET @preparedStatement = (SELECT IF(  (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS    WHERE table_schema = @dbname    AND table_name = @tablename    AND column_name = @columnname) > 0,  'SELECT 1',  CONCAT('ALTER TABLE ', @tablename, ' ADD COLUMN ', @columnname, ' VARCHAR(500)')
));
PREPARE alterIfNotExists FROM @preparedStatement;EXECUTE alterIfNotExists;DEALLOCATE PREPARE alterIfNotExists;